INSERT INTO NOMBREFECHA (NOMBRE, FECHACREACION, USUARIOCREACION) SELECT n, NOW(), 'seeder' FROM (VALUES -- Resaltadas ('Inicio del periodo'), ('Matrículas académicas estudiantes regulares'), ('Inicio de clases'), ('Plazo máximo para presentar solicitudes de cancelación de asignaturas y/o matrícula del {calendar}, debidamente justificadas'), ('Registro de Notas 70% en SIMCA'), ('Evaluación docente {calendar}'), ('Finalización de clases'), ('Plazo máximo para finales, supletorios y habilitaciones a cargo de profesores de cátedra'), ('Cierre de SIMCA para registro de calificaciones'), ('Finalización de periodo académico {calendar}'),
-- No resaltadas ('Inducción a estudiantes de primer semestre, periodo académico {calendar}'), ('Ajustes de matrícula SIMCA'), ('Adiciones matrícula a través del módulo SIMCA (KIRA)'), ('Listas definitivas de clase'), ('PRIMEROS PARCIALES'), ('Plazo para registro de notas primeros parciales'), ('SEGUNDOS PARCIALES'), ('Plazo máximo para recepción de solicitudes de reingreso {calendar}'), ('Exámenes finales, supletorios, habilitaciones y validaciones - profesores de planta y ocasionales'), ('Planeación de cursos especiales'), ('Desarrollo de cursos especiales'),
-- Administrativas ('Solicitud de presentación de nuevas electivas al consejo de facultad'), ('Reporte de las electivas a ofrecer por el departamento'), ('Presentación de electivas y líneas de énfasis'), ('Pre-inscripción de electivas y líneas de énfasis'),
-- Caracter adicional ('SEMANAS DE CLASE'), ('SEMANAS DE OCASIONALES'), ('SEMANAS DE CATEDRA'), ('SEMANAS DE PLANTA'), ('SEMANAS DE BECARIO Y PRACTICANTE')
) AS t(n) ON CONFLICT (NOMBRE) DO NOTHING;
